pub fn appendRouteEntryPointsIfNotStale(dev: *DevServer, entry_points: *EntryPointList, alloc: Allocator, rbi: RouteBundle.Index) bun.OOM!void {
        const server_file_names = dev.server_graph.bundled_files.keys();
        const client_file_names = dev.client_graph.bundled_files.keys();
        switch (dev.routeBundlePtr(rbi).data) {
.framework => |*bundle| {
var route = dev.router.routePtr(bundle.route_index);
        _ = &route;
        const router_type = dev.router.typePtr(route.@"type");
        _ = try dev.appendOpaqueEntryPoint(server_file_names, entry_points, alloc, .server, router_type.server_file);
        _ = try dev.appendOpaqueEntryPoint(client_file_names, entry_points, alloc, .client, router_type.client_file);
        _ = try dev.appendOpaqueEntryPoint(server_file_names, entry_points, alloc, .server, route.file_page);
        _ = try dev.appendOpaqueEntryPoint(server_file_names, entry_points, alloc, .server, route.file_layout);
        while (route.parent.unwrap()) |parent_index| {
            route = dev.router.routePtr(parent_index);
            _ = try dev.appendOpaqueEntryPoint(server_file_names, entry_points, alloc, .server, route.file_layout);
        }
},
.html => |*html| {
_ = try entry_points.append(alloc, html.html_bundle.data.bundle.data.path, .{ .client = true });
},
}
        if (dev.has_tailwind_plugin_hack) |*map| {
            _ = &map;
            for (cp_iter_slice((map.*).keys())) |abs_path| {
                _ = &abs_path;
                const opt_bf = dev.client_graph.bundled_files.get(abs_path);
                if ((opt_bf == null)) {
                    continue;
                }
                const file = opt_bf.?.unpack();
                if ((file.kind() == .css)) {
                    _ = bun.handleOom(entry_points.appendCss(alloc, abs_path));
                }
            }
        }
}

