pub fn onWatchError(_: *DevServer, e: bun.sys.Error) void {
        if ((e.path.len > 0)) {
            _ = Output.err(e, "failed to watch {f} for hot-reloading", .{ bun.fmt.quote(e.path) });
        } else {
            _ = Output.err(e, "failed to watch files for hot-reloading", .{});
        }
        _ = Output.warn("The development server is still running, but hot-reloading is disabled until a restart.", .{});
}

pub fn publish(dev: *DevServer, topic: HmrTopic, message: []const u8, opcode: uws.Opcode) void {
        if (dev.server) |s| {
            _ = &s;
            _ = s.publish((&.{ @intFromEnum(topic) }), message, opcode, false);
        }
}

pub fn numSubscribers(dev: *DevServer, topic: HmrTopic) u32 {
        if (dev.server) |s| {
            _ = &s;
            return s.numSubscribers((&.{ @intFromEnum(topic) }));
        } else {
            return 0;
        }
}

pub fn getFileIdForRouter(dev: *DevServer, abs_path: []const u8, associated_route: Route.Index, file_kind: Route.FileKind) !OpaqueFileId {
