pub fn toOpaqueFileId(comptime side: bake.Side, index: IncrementalGraph(side).FileIndex) OpaqueFileId {
        if (Environment.allow_assert) {
            return OpaqueFileId.init(@bitCast(SafeFileId{ .side = side, .index = index.get() }));
        }
        return OpaqueFileId.init(index.get());
}

pub fn fromOpaqueFileId(comptime side: bake.Side, id: OpaqueFileId) IncrementalGraph(side).FileIndex {
        if (Environment.allow_assert) {
            const safe: SafeFileId = @bitCast(id.get());
            _ = assert((side == safe.side));
            return IncrementalGraph(side).FileIndex.init(safe.index);
        }
        return IncrementalGraph(side).FileIndex.init(@intCast(id.get()));
}

