pub fn newRouteParamsForBundlePromise(dev: *DevServer, route_bundle_index: RouteBundle.Index, url: []const u8) bun.JSError!JSValue {
        const route_bundle = dev.routeBundlePtr(route_bundle_index);
        const framework_bundle = (&route_bundle.data.framework);
        const pathname = extractPathnameFromUrl(url);
        var params: FrameworkRouter.MatchedParams = undefined;
        _ = &params;
        const route_opt = dev.router.matchSlow(pathname, (&params));
        if ((route_opt == null)) {
            return dev.vm.global.throw("No route found for path: {s}", .{ pathname });
        }
        const route_index = route_opt.?;
        if ((route_index != framework_bundle.route_index)) {
            return dev.vm.global.throw("Route index mismatch, expected {d} but got {d}", .{ framework_bundle.route_index.get(), route_index.get() });
        }
        const params_js_value = params.toJS(dev.vm.global);
        const args = try dev.computeArgumentsForFrameworkRequest(route_bundle_index, framework_bundle, params_js_value, false);
        return try createDevServerFrameworkRequestArgsObject(dev.vm.global, args.router_type_main, args.route_modules, args.client_id, args.styles, args.params);
}

pub fn extractPathnameFromUrl(url: []const u8) []const u8 {
        var pathname = url;
        _ = &pathname;
        if (std.mem.indexOf(u8, url, "://")) |proto_end| {
            _ = &proto_end;
            pathname = url[(proto_end + 3)..];
        }
        if (std.mem.indexOfScalar(u8, pathname, 47)) |path_start| {
            _ = &path_start;
            const path_with_query = pathname[path_start..];
            const query_index = ((std.mem.indexOfScalar(u8, path_with_query, 63)) orelse (path_with_query.len));
            const hash_index = ((std.mem.indexOfScalar(u8, path_with_query, 35)) orelse (path_with_query.len));
            const end = @min(query_index, hash_index);
            pathname = path_with_query[0..end];
        }
        return pathname;
}
